"use strict";
const $=id=>document.getElementById(id);
const storageKey="pico-chat-delta-qat-compatible-v1";
let messages=[],busy=false,clearing=false,online=false,controller=null,generation=0,toastTimer;
try{const stored=JSON.parse(localStorage.getItem(storageKey)||"[]");if(Array.isArray(stored))messages=stored.filter(m=>m&&["user","assistant"].includes(m.role)&&typeof m.content==="string").slice(-200).map(m=>({...m,queue:undefined,streaming:false,interrupted:m.interrupted||m.streaming}));}catch{}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(messages.slice(-200)));}catch{}}
function toast(text){$("toast").textContent=text;$("toast").hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$("toast").hidden=true,2800);}
function bottom(force=false){if(force||window.innerHeight+window.scrollY>=document.body.scrollHeight-230)window.scrollTo({top:document.body.scrollHeight,behavior:"instant"});}
function messageNode(m){const row=document.createElement("article");row.className="message "+m.role+(m.streaming?" streaming":"");if(m.role==="assistant"){const head=document.createElement("div");head.className="assistant-heading";const icon=document.createElement("span");icon.className="tiny-grid";icon.setAttribute("aria-hidden","true");head.append(icon,document.createTextNode("PICO"));row.append(head);}const text=document.createElement("div");text.className="bubble";text.textContent=m.content;row.append(text);if(m.role==="assistant"){const meta=document.createElement("div");meta.className="message-meta";if(m.error){meta.classList.add("message-error");meta.textContent=m.error;}else if(m.queue){meta.textContent=`排队中 · 当前第 ${m.queue} 位`; }else if(m.stats){const first=m.stats.first_token_ms;meta.textContent=`${m.stats.output_tokens} token · ${Number(m.stats.tokens_per_second).toFixed(1)} token/s${first!=null?` · 首字 ${Math.round(first)} ms`:""}${m.interrupted?" · 已停止":""}`;}else if(m.interrupted){meta.textContent="已停止";}row.append(meta);}return row;}
function render(){document.body.classList.toggle("has-messages",messages.length>0);$("messages").replaceChildren(...messages.map(messageNode));updateControls();}
function updateControls(){$("send").disabled=clearing||(!busy&&(!$("input").value.trim()||!online));$("send-label").textContent=busy?"停止":"发送";$("send-icon").hidden=busy;$("stop-icon").hidden=!busy;$("send").classList.toggle("stopping",busy);$("send").setAttribute("aria-label",busy?"停止生成":"发送消息");$("length").disabled=busy||clearing;$("clear").disabled=clearing;}
function setOnline(value){online=value;$("connection").className="connection "+(value?"online":"offline");$("connection-label").textContent=value?"NPU 在线":"板子未连接";updateControls();}
async function health(){if(busy||clearing)return;try{const r=await fetch("/api/health",{signal:AbortSignal.timeout(3000)});const data=await r.json();setOnline(r.ok&&data.online);if(data.model){$("model-label").textContent=data.model.label;$("model-note").textContent=data.model.note+` 每次最多保留 ${data.model.context_tokens} token 对话。`; }if(data.queue){$("queue-label").textContent=data.queue.busy?`有人正在体验 · ${data.queue.waiting} 人排队`:"空闲 · 可以开始聊天";}}catch{setOnline(false);}}
function resize(){const el=$("input");el.style.height="auto";el.style.height=Math.min(el.scrollHeight,180)+"px";updateControls();}
function historyFor(current){const retained=[];for(let i=0;i<messages.length-2;i+=2){const u=messages[i],a=messages[i+1];if(u?.role==="user"&&a?.role==="assistant"&&a.content&&!a.error)retained.push({role:"user",content:u.content},{role:"assistant",content:a.content});}return [...retained.slice(-198),{role:"user",content:current}];}
async function consume(response,onEvent){const reader=response.body.getReader(),decoder=new TextDecoder();let pending="";try{for(;;){const {value,done}=await reader.read();pending+=done?decoder.decode():decoder.decode(value,{stream:true});let p;while((p=pending.indexOf("\n\n"))>=0){const block=pending.slice(0,p);pending=pending.slice(p+2);let type="message",data=[];for(const line of block.split("\n")){if(line.startsWith("event: "))type=line.slice(7);if(line.startsWith("data: "))data.push(line.slice(6));}if(data.length)onEvent(type,JSON.parse(data.join("\n")));}if(done)break;}}finally{reader.releaseLock();}}
async function send(event){event?.preventDefault();if(busy){controller?.abort();return;}if(clearing||!online)return;const content=$("input").value.trim();if(!content)return;const id=++generation;controller=new AbortController();busy=true;$("queue-label").textContent="正在提交本轮对话…";$("notice").hidden=true;messages.push({role:"user",content},{role:"assistant",content:"",streaming:true});const answer=messages[messages.length-1],payload=historyFor(content);$("input").value="";resize();render();persist();bottom(true);let finished=false,lastPaint=0;
  try{const response=await fetch("/api/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({messages:payload,max_new_tokens:Number($("length").value)}),signal:controller.signal});if(!response.ok){const e=await response.json();throw Error(e.error||"发送失败，请重试。");}await consume(response,(type,data)=>{if(id!==generation)return;if(type==="meta"&&data.truncated){$("notice").textContent="上下文较长，本轮优先保留最近的对话内容。";$("notice").hidden=false;}else if(type==="queue"){answer.queue=data.position;$("queue-label").textContent=`已进入队列 · 当前第 ${data.position} 位`;render();}else if(type==="start"){delete answer.queue;$("queue-label").textContent="轮到你了 · 卷语正在回答";render();}else if(type==="delta"){answer.content=data.text;const now=performance.now();if(now-lastPaint>30){render();bottom();lastPaint=now;}}else if(type==="done"){answer.content=data.text;answer.stats=data;answer.streaming=false;finished=true;}else if(type==="error"){throw Error(data.error);}});if(!finished&&id===generation)throw Error("回答连接已中断，请重试。");
  }catch(error){if(id!==generation)return;if(error.name==="AbortError"){answer.interrupted=true;}else{answer.error=error.message||"连接异常，请重试。";toast(answer.error);}}finally{if(id===generation){delete answer.queue;answer.streaming=false;busy=false;controller=null;render();persist();bottom();$("input").focus();health();}}}
async function clearChat(){if(clearing)return;generation++;controller?.abort();controller=null;busy=false;clearing=true;messages=[];persist();render();$("notice").hidden=true;try{const response=await fetch("/api/reset",{method:"POST",headers:{"Content-Type":"application/json"},body:"{}",signal:AbortSignal.timeout(5000)});toast(response.ok?"对话已清空":"本地对话已清空，板端暂不可用。");}catch{toast("本地对话已清空。");}finally{clearing=false;updateControls();health();$("input").focus();}}
$("chat-form").addEventListener("submit",send);$("clear").addEventListener("click",clearChat);$("input").addEventListener("input",resize);$("input").addEventListener("keydown",event=>{if(event.key==="Enter"&&!event.shiftKey&&!event.isComposing){event.preventDefault();send();}});document.querySelectorAll("[data-prompt]").forEach(button=>button.addEventListener("click",()=>{if(busy||clearing)return;$("input").value=button.dataset.prompt;resize();send();}));render();health();setInterval(health,10000);
